```haskell
data ExprTree = Val Int | Node Char ExprTree ExprTree deriving Show
 
parseExpr :: String -> ExprTree
parseExpr = parse . words
  where
    parse [] = error "Empty expression"
    parse [x] = Val $ read x
    parse (x:xs)
      | isOp x = Node x (parse lft) (parse rgt)
      | otherwise = Val $ read x
      where
        (lft, rgt) = splitAt (length xs `div` 2) xs
 
isOp :: String -> Bool
isOp = flip elem "+-*"
 
showExpr :: ExprTree -> String
showExpr (Val n) = show n
showExpr (Node op l r) = "(" ++ showExpr l ++ " " ++ op ++ " " ++ showExpr r ++ ")"
 
main :: IO ()
main = do
  putStrLn $ showExpr $ parseExpr "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3"
